WITH source AS (
    SELECT
        product_index,
        portion_index,
        btrim(replace(product->>'name', chr(160), ' ')) AS name,
        btrim(product->>'brand') AS brand,
        btrim(portion->>'label') AS label,
        NULLIF(portion->>'piece_count', '')::integer AS piece_count,
        (portion->'serving_size'->>'value')::double precision AS serving_amount,
        btrim(portion->'serving_size'->>'unit') AS nutrition_unit,
        btrim(portion->'nutrition'->>'per') AS nutrition_basis,
        (portion->'nutrition'->>'calories_kcal')::double precision AS calories,
        (portion->'nutrition'->>'protein_g')::double precision AS protein,
        (portion->'nutrition'->>'fat_g')::double precision AS fat,
        (portion->'nutrition'->>'carbohydrates_g')::double precision AS carbohydrate
    FROM fast_food_moscow_dataset
    CROSS JOIN LATERAL jsonb_array_elements(payload->'products') WITH ORDINALITY AS products(product, product_index)
    CROSS JOIN LATERAL jsonb_array_elements(product->'portion_options') WITH ORDINALITY AS portions(portion, portion_index)
    WHERE COALESCE((portion->>'available')::boolean, FALSE)
      AND EXISTS (
          SELECT 1 FROM jsonb_array_elements(portion->'skus') AS sku(value)
          WHERE COALESCE((value->>'available')::boolean, FALSE)
      )
),
valid AS (
    SELECT *
    FROM source
    WHERE name <> ''
      AND brand IN ('ВКУСНО — И ТОЧКА', 'БУРГЕР КИНГ', 'ROSTIC''S')
      AND label <> ''
      AND serving_amount BETWEEN 0.1 AND 10000
      AND nutrition_unit IN ('g', 'ml')
      AND nutrition_basis = '100 ' || nutrition_unit
      AND calories BETWEEN 0 AND 1000
      AND protein BETWEEN 0 AND 100
      AND fat BETWEEN 0 AND 100
      AND carbohydrate BETWEEN 0 AND 100
),
deduplicated AS (
    SELECT *, row_number() OVER (
        PARTITION BY lower(brand), lower(name), lower(label)
        ORDER BY product_index, portion_index
    ) AS label_rank
    FROM valid
),
products AS (
    SELECT
        brand,
        name,
        (array_agg(nutrition_unit ORDER BY product_index, portion_index))[1] AS nutrition_unit,
        (array_agg(calories ORDER BY product_index, portion_index))[1] AS calories,
        (array_agg(protein ORDER BY product_index, portion_index))[1] AS protein,
        (array_agg(fat ORDER BY product_index, portion_index))[1] AS fat,
        (array_agg(carbohydrate ORDER BY product_index, portion_index))[1] AS carbohydrate,
        jsonb_agg(
            jsonb_build_object(
                'id', 'portion-' || md5(lower(label)),
                'description', label,
                'metricAmount', serving_amount,
                'metricUnit', nutrition_unit,
                'numberOfUnits', 1,
                'measurement', 'порция',
                'calories', calories * serving_amount / 100.0,
                'carbohydrate', carbohydrate * serving_amount / 100.0,
                'protein', protein * serving_amount / 100.0,
                'fat', fat * serving_amount / 100.0
            ) ORDER BY piece_count NULLS LAST, serving_amount, label
        ) AS portion_servings
    FROM deduplicated
    WHERE label_rank = 1
    GROUP BY brand, name
),
prepared AS (
    SELECT
        'fast-food-moscow-' || md5(lower(brand) || ':' || lower(name)) AS external_id,
        brand,
        name,
        calories,
        protein,
        fat,
        carbohydrate,
        jsonb_build_array(jsonb_build_object(
            'id', nutrition_unit,
            'description', CASE nutrition_unit WHEN 'ml' THEN 'мл' ELSE 'г' END,
            'metricAmount', 1,
            'metricUnit', nutrition_unit,
            'numberOfUnits', 100,
            'measurement', CASE nutrition_unit WHEN 'ml' THEN 'мл' ELSE 'г' END,
            'calories', calories,
            'carbohydrate', carbohydrate,
            'protein', protein,
            'fat', fat
        )) || portion_servings AS servings
    FROM products
)
INSERT INTO food_catalog (
    provider, external_id, barcode, name, brand_name, description,
    calories_per_100g, carbohydrate_per_100g, protein_per_100g, fat_per_100g,
    servings, data_quality
)
SELECT
    'community', external_id, '', name, brand, '',
    calories, carbohydrate, protein, fat, servings, 0.98
FROM prepared
ON CONFLICT (provider, external_id) DO UPDATE SET
    name = EXCLUDED.name,
    brand_name = EXCLUDED.brand_name,
    description = EXCLUDED.description,
    calories_per_100g = EXCLUDED.calories_per_100g,
    carbohydrate_per_100g = EXCLUDED.carbohydrate_per_100g,
    protein_per_100g = EXCLUDED.protein_per_100g,
    fat_per_100g = EXCLUDED.fat_per_100g,
    servings = EXCLUDED.servings,
    data_quality = EXCLUDED.data_quality,
    cached_at = now();

-- Keep existing diary entries editable after SKU cards are replaced by grouped products.
WITH mapping AS (
    SELECT DISTINCT
        'fast-food-moscow-' || md5(lower(btrim(product->>'brand')) || ':' || btrim(sku->>'code')) AS old_external_id,
        'fast-food-moscow-' || md5(lower(btrim(product->>'brand')) || ':' || lower(btrim(replace(product->>'name', chr(160), ' ')))) AS new_external_id
    FROM fast_food_moscow_dataset
    CROSS JOIN LATERAL jsonb_array_elements(payload->'products') AS products(product)
    CROSS JOIN LATERAL jsonb_array_elements(product->'portion_options') AS portions(portion)
    CROSS JOIN LATERAL jsonb_array_elements(portion->'skus') AS skus(sku)
    WHERE btrim(sku->>'code') ~ '^[A-Za-z0-9_-]+$'
)
UPDATE user_nutrition_entries AS entry
SET food_id = grouped.id
FROM mapping
JOIN food_catalog AS previous
  ON previous.provider = 'community' AND previous.external_id = mapping.old_external_id
JOIN food_catalog AS grouped
  ON grouped.provider = 'community' AND grouped.external_id = mapping.new_external_id
WHERE entry.food_id = previous.id;

WITH current_products AS (
    SELECT DISTINCT
        'fast-food-moscow-' || md5(lower(btrim(product->>'brand')) || ':' || lower(btrim(replace(product->>'name', chr(160), ' ')))) AS external_id
    FROM fast_food_moscow_dataset
    CROSS JOIN LATERAL jsonb_array_elements(payload->'products') AS products(product)
)
DELETE FROM food_catalog
WHERE provider = 'community'
  AND external_id LIKE 'fast-food-moscow-%'
  AND external_id NOT IN (SELECT external_id FROM current_products);
